<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap/app.php';
$admin=pf_require_admin($pdo);$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$key=(string)($_POST['placement_key']??'');$currency=strtoupper((string)($_POST['currency']??''));$price=filter_var($_POST['price_per_day']??null,FILTER_VALIDATE_FLOAT);$active=isset($_POST['is_active'])?1:0;$min=max(1,(int)($_POST['min_duration_days']??1));$max=max($min,(int)($_POST['max_duration_days']??365));
 if($key===''||!in_array($currency,['USD','NGN'],true)||$price===false||$price<0||$price>1000000||$max>3650||($active===1&&$price<=0))$error='Enter a valid currency, price and duration. Active prices must be greater than zero.';
 else{$q=$pdo->prepare('UPDATE pf_ad_placement_prices SET price_per_day=?,min_duration_days=?,max_duration_days=?,is_active=? WHERE placement_key=? AND currency=?');$q->execute([$price,$min,$max,$active,$key,$currency]);$notice='Placement pricing saved.';}
}
$rows=$pdo->query('SELECT p.placement_key,p.surface,p.label,p.description,pr.currency,pr.price_per_day,pr.min_duration_days,pr.max_duration_days,pr.is_active FROM pf_ad_placements p JOIN pf_ad_placement_prices pr ON pr.placement_key=p.placement_key ORDER BY p.surface,p.sort_order,p.label,pr.currency')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Placement pricing | PoketFlow</title><link rel="stylesheet" href="../assets/marketplace.css"><style>.placement{padding:18px 0;border-bottom:1px solid var(--line)}.placement form{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.placement label{display:grid;gap:5px;font-size:12px;font-weight:700}.placement input{padding:9px;border:1px solid var(--line);border-radius:9px;max-width:130px}</style></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="index.php">Admin home</a><a href="advertisers.php">Advertisers</a><a href="finance.php">Finance</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">INVENTORY & PRICING</p><h1>Advertising placements</h1><p class="muted">Set separate daily prices for USD and NGN campaigns. Prices are administrator-controlled. Keep a currency disabled until its actual rate is approved.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><?php if($notice):?><div class="panel"><?=pf_e($notice)?></div><?php endif;?><section class="panel"><?php foreach($rows as $r):?><div class="placement"><p class="eyebrow"><?=pf_e($r['surface'])?> · <?=pf_e($r['placement_key'])?> · <?=pf_e($r['currency'])?></p><h2><?=pf_e($r['label'])?></h2><p class="muted"><?=pf_e((string)$r['description'])?></p><form method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="placement_key" value="<?=pf_e($r['placement_key'])?>"><input type="hidden" name="currency" value="<?=pf_e($r['currency'])?>"><label>Price/day (<?=pf_e($r['currency'])?>)<input type="number" name="price_per_day" min="0" step="0.01" value="<?=pf_e((string)$r['price_per_day'])?>"></label><label>Min days<input type="number" name="min_duration_days" min="1" max="3650" value="<?=(int)$r['min_duration_days']?>"></label><label>Max days<input type="number" name="max_duration_days" min="1" max="3650" value="<?=(int)$r['max_duration_days']?>"></label><label>Active<input type="checkbox" name="is_active" value="1" <?=$r['is_active']?'checked':''?>></label><button class="button primary" type="submit">Save pricing</button></form></div><?php endforeach;?></section></main></body></html>
